import React, { useState, useRef, useEffect } from 'react';

const CameraProcessor = ({ colorblindType = 'protanopia', mode = 'simulate' }) => {
  const [streaming, setStreaming] = useState(false);
  const [error, setError] = useState(null);
  const videoRef = useRef(null);

  useEffect(() => {
    return () => stopCamera(); // cleanup on unmount
  }, []);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
      videoRef.current.srcObject = stream;
      videoRef.current.play();
      setStreaming(true);
      setError(null);
    } catch (err) {
      setError('Camera access error: ' + err.message);
    }
  };

  const stopCamera = () => {
    if (videoRef.current?.srcObject) {
      videoRef.current.srcObject.getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setStreaming(false);
  };

  return (
    <div className="component-container">
      <h2>Live Camera</h2>

      <div
        className="upload-area"
        style={{
          textAlign: 'center',
          padding: '40px 20px',
          border: '2px dashed #ccc',
          borderRadius: '8px',
          backgroundColor: '#fafafa',
          cursor: 'pointer',
        }}
        onClick={streaming ? stopCamera : startCamera}
      >
        {!streaming ? (
          <>
            <p style={{ fontSize: '16px' }}>Click to start your camera</p>
            <p style={{ fontSize: '14px', color: '#666' }}>Your live feed will appear below</p>
          </>
        ) : (
          <p style={{ fontSize: '16px' }}>✓ Camera is active (click to stop)</p>
        )}
      </div>

      {error && <div style={{ color: 'red', marginTop: '10px' }}>{error}</div>}

      {streaming && (
        <div style={{ marginTop: '20px', textAlign: 'center' }}>
          <video
            ref={videoRef}
            style={{
              width: '100%',
              maxWidth: '640px',
              borderRadius: '8px',
              border: '2px solid #ddd',
            }}
            autoPlay
            playsInline
            muted
          />
        </div>
      )}

      <div style={{ textAlign: 'center', marginTop: '20px' }}>
        <button onClick={streaming ? stopCamera : startCamera}>
          {streaming ? 'Stop Camera' : 'Start Camera'}
        </button>
      </div>
    </div>
  );
};

export default CameraProcessor;
